type genqlientInput interface {
	GetIndex() int
	GetStatus() CompletionStatus
	GetMsgSender() string
	GetTimestamp() string
	GetBlockNumber() string
	GetPayload() string
}

func inputFromGenqlient(input genqlientInput) (Input, error) {
	timestamp, err := strconv.ParseUint(input.GetTimestamp(), 0, 64)
	if err != nil {
		return Input{}, fmt.Errorf("failed to parse timestamp: %v", err)
	}

	blocknumber, err := strconv.ParseUint(input.GetBlockNumber(), 0, 64)
	if err != nil {
		return Input{}, fmt.Errorf("failed to parse block number: %v", err)
	}
	payload, err := hexutil.Decode(input.GetPayload())
	if err != nil {
		return Input{}, fmt.Errorf("failed to decode payload to bytes: %v", err)
	}

	return Input{
		input.GetIndex(),
		input.GetStatus(),
		common.HexToAddress(input.GetMsgSender()),
		time.Duration(timestamp),
		blocknumber,
		payload,
	}, nil
}

func GetInput(
	ctx context.Context,
	client graphql.Client,
	index int,
) (*Input, error) {
	resp, err := getInput(ctx, client, int(index))
	if err != nil {
		return nil, err
	}

	input, err := inputFromGenqlient(&resp.Input)
	if err != nil {
		return nil, err
	}

	return &input, nil
}

func GetInputs(
	ctx context.Context,
	client graphql.Client,
	first int,
) ([]Input, error) {

	var inputs []Input

	resp, err := getInputs(ctx, client, int(first))
	if err != nil {
		return nil, err
	}

	for _, edge := range resp.Inputs.Edges {
		input, err := inputFromGenqlient(&edge.Node)
		if err != nil {
			return nil, err
		}

		inputs = append(inputs, input)
	}

	return inputs, err
}
